import openpyxl
orig=openpyxl.load_workbook('/workspace/input.xlsx', data_only=False)['Model']
out=openpyxl.load_workbook('/workspace/output.xlsx', data_only=False)['Model']
print('Changed cells:')
for row in orig.iter_rows():
    for c in row:
        if c.value != out[c.coordinate].value:
            print(c.coordinate, 'from', repr(c.value), 'to', repr(out[c.coordinate].value))
print('\nRemaining suspicious formulas in output:')
for row in out.iter_rows():
    for c in row:
        v = c.value
        if isinstance(v,str) and v.startswith('='):
            if '1+(' in v or 'H77' in v or 'N35' in v or '+N35' in v or 'N35+' in v or '=1+' in v or '=N35' in v or 'N35/((1+$C$14)^N33)' in v and c.coordinate!='N35':
                print('SUSP', c.coordinate, v)
print('\nHard-coded numbers in rows 42-89 formulas region:')
for r in range(42, 90):
    for col in range(1, 16):
        c=out.cell(r,col)
        if isinstance(c.value,(int,float)):
            print(c.coordinate, c.value)
print('\nOutput file info')
import os
print(os.path.getsize('/workspace/output.xlsx'))
